-- Упражнения книги 17, глава 25 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'virt-sim-ovirt-triage', 0, 'lab', 'Доска: поиск неисправности', 'Доска с уже собранной, но сломанной средой. В рассказе только симптомы: выберите объекты, прочитайте причины в инспекторе и путь сообщений, найдите уровень и почините доску. Пять сценариев: молчащий хост и машина без сети, дата-центр без мастер-домена, хосты после добавления iSCSI, кластер вне дата-центра и всё красное из-за менеджера. Упражнение решено, когда решены все сценарии.', '', 'Идите от симптома к уровню: NonResponsive — сеть управления, NonOperational — сеть или хранилище хоста, Uninitialized — мастер-домен, No cluster — членство. Запускайте операции и читайте путь сообщений.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'virt-sim-ovirt-triage-2', 1, 'lab', 'Доска: поиск неисправности, сложнее', 'Те же приёмы на более крупных досках: два кластера или два дата-центра и несколько машин. Пять сценариев: новый хост, который исправляется по слою за раз, машина, которую рассказ обвиняет в диске, зелёная доска с падающей миграцией, машина и хост удалённого дата-центра и домен, объявленный не тем типом. Упражнение решено, когда решены все сценарии.', '', 'Не верьте рассказу, верьте статусам и пути сообщений. После каждой правки читайте статусы заново: одна неисправность может прятать другую, а зелёные статусы не гарантируют, что операция пройдёт.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-upgrade-plan', 2, 'func', 'План обновления', 'Модель обновления. Ступени версий по порядку: "4.3", "4.4", "4.5" (других нет). Даны версия менеджера engine, словарь hosts (имя хоста → версия), версия совместимости кластера cluster, версия центра данных dc и целевая ступень target. Состояние допустимо, только если выполнено всё: все версии есть в списке ступеней и ни одна не выше target; ни один хост не новее менеджера; версия кластера не выше версии ни одного хоста; версия центра данных не выше версии кластера. Если состояние недопустимо, верните None. Иначе верните список шагов-строк. Идите по ступеням v от следующей за самой старой версией среди менеджера и хостов до target включительно. Для каждой ступени v: если менеджер ниже v, добавьте "backup" и "engine:v"; затем для каждого хоста в алфавитном порядке имён, если он ниже v, добавьте "maintenance:имя", "host:имя:v" и "activate:имя". После всех ступеней добавьте по шагу "cluster:v" для каждой ступени выше версии кластера (по возрастанию), затем так же "dc:v" для центра данных. Если делать нечего, верните пустой список.', 'def upgrade_plan(engine, hosts, cluster, dc, target):
    pass
', 'Список ступеней L = ["4.3", "4.4", "4.5"], ранг — L.index(v). Сначала проверки на None, потом три цикла: по ступеням с хостами, по кластеру, по центру данных. Копируйте версии хостов в локальный словарь, чтобы обновлять их по ходу.', '{"func": "upgrade_plan", "tests": [{"args": ["4.4", {"h1": "4.4", "h2": "4.4"}, "4.4", "4.4", "4.5"], "expected": ["backup", "engine:4.5", "maintenance:h1", "host:h1:4.5", "activate:h1", "maintenance:h2", "host:h2:4.5", "activate:h2", "cluster:4.5", "dc:4.5"]}, {"args": ["4.5", {"h1": "4.5"}, "4.5", "4.5", "4.5"], "expected": []}, {"args": ["4.3", {"h1": "4.3"}, "4.3", "4.3", "4.5"], "expected": ["backup", "engine:4.4", "maintenance:h1", "host:h1:4.4", "activate:h1", "backup", "engine:4.5", "maintenance:h1", "host:h1:4.5", "activate:h1", "cluster:4.4", "cluster:4.5", "dc:4.4", "dc:4.5"]}, {"args": ["4.4", {"h1": "4.5"}, "4.4", "4.4", "4.5"], "expected": null}, {"args": ["4.4", {"h1": "4.4"}, "4.4", "4.4", "4.6"], "expected": null}, {"args": ["4.5", {"b": "4.4", "a": "4.5"}, "4.4", "4.4", "4.5"], "expected": ["maintenance:b", "host:b:4.5", "activate:b", "cluster:4.5", "dc:4.5"]}, {"args": ["4.5", {"h1": "4.5"}, "4.4", "4.5", "4.5"], "expected": null}, {"args": ["4.5", {"h1": "4.5"}, "4.5", "4.5", "4.4"], "expected": null}, {"args": ["4.4", {}, "4.4", "4.4", "4.5"], "expected": ["backup", "engine:4.5", "cluster:4.5", "dc:4.5"]}, {"args": ["4.5", {"h1": "4.3", "h2": "4.4"}, "4.3", "4.3", "4.5"], "expected": ["maintenance:h1", "host:h1:4.4", "activate:h1", "maintenance:h1", "host:h1:4.5", "activate:h1", "maintenance:h2", "host:h2:4.5", "activate:h2", "cluster:4.4", "cluster:4.5", "dc:4.4", "dc:4.5"]}, {"args": ["4.4", {"h1": "4.4"}, "4.5", "4.4", "4.5"], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-parse-engine-line', 3, 'func', 'Разбор строки engine.log', 'Строка журнала менеджера имеет вид: "2026-03-01 10:15:42,123+01 INFO  [org.ovirt.engine.core.bll.RunVmCommand] (default task-5) [5f2a] Running command". Порядок полей: дата и время с миллисекундами (три цифры) и смещением часового пояса (знак и две цифры); уровень DEBUG, INFO, WARN или ERROR, после него один или несколько пробелов; полное имя класса в квадратных скобках; поток в круглых скобках; идентификатор корреляции в квадратных скобках (может быть пустым); один пробел и текст сообщения (может содержать скобки и быть пустым). Напишите функцию parse_engine_line(line): верните кортеж из пяти строк — (дата и время без миллисекунд и пояса в виде "2026-03-01 10:15:42", уровень, последняя часть имени класса после последней точки, идентификатор корреляции, текст). Если строка не подходит под формат (в том числе неизвестный уровень или нет миллисекунд), верните None.', 'def parse_engine_line(line):
    pass
', 'Регулярное выражение с группами: уровень и пробелы, затем [^\]]* для скобок класса и корреляции, [^)]* для потока. Класс режьте по точке: split(''.'')[-1].', '{"func": "parse_engine_line", "tests": [{"args": ["2026-03-01 10:15:42,123+01 INFO  [org.ovirt.engine.core.bll.RunVmCommand] (default task-5) [5f2a] Running command: RunVmCommand"], "expected": {"__tuple__": ["2026-03-01 10:15:42", "INFO", "RunVmCommand", "5f2a", "Running command: RunVmCommand"]}}, {"args": ["2026-03-01 10:15:43,007+00 ERROR [org.ovirt.engine.core.vdsbroker.vdsbroker.CreateBrokerVDSCommand] (EE-ManagedThreadFactory-engine-Thread-3) [] Failed in ''CreateVDS'' method"], "expected": {"__tuple__": ["2026-03-01 10:15:43", "ERROR", "CreateBrokerVDSCommand", "", "Failed in ''CreateVDS'' method"]}}, {"args": ["2026-03-01 10:15:44,500-02 WARN  [org.ovirt.engine.core.bll.Foo] (x) [ab] Lock [timeout] busy"], "expected": {"__tuple__": ["2026-03-01 10:15:44", "WARN", "Foo", "ab", "Lock [timeout] busy"]}}, {"args": ["2026-03-01 10:15:44,500+01 TRACE [a.B] (x) [ab] hi"], "expected": null}, {"args": ["garbage line"], "expected": null}, {"args": ["2026-03-01 10:15:44+01 INFO  [a.B] (x) [ab] no millis"], "expected": null}, {"args": ["2026-03-01 10:15:45,001+01 DEBUG [Plain] (t) [c1] "], "expected": {"__tuple__": ["2026-03-01 10:15:45", "DEBUG", "Plain", "c1", ""]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-command-timelines', 4, 'func', 'Таймлайны команд по корреляции', 'Строки журналов с разных узлов слиты в один список в произвольном порядке. Формат строки: "ЧЧ:ММ:СС УРОВЕНЬ источник corr текст…" — четыре слова через пробелы, потом необязательный текст. Строки, где меньше четырёх слов, где время не вида ЧЧ:ММ:СС (две цифры, двоеточие, две цифры, двоеточие, две цифры) или где corr равен "-", пропускаются. Напишите функцию command_timelines(lines): верните словарь corr → словарь с ключами "start" (самое раннее время строкой), "end" (самое позднее), "duration" (end минус start в секундах, целое; все строки в пределах одних суток), "errors" (сколько строк с уровнем ERROR) и "sources" (отсортированный список различных источников). Для пустого входа верните пустой словарь.', 'def command_timelines(lines):
    pass
', 'line.split(None, 4) даёт до пяти частей. Время переведите в секунды, чтобы искать минимум и максимум; строка времени вида ЧЧ:ММ:СС сама по себе сортируется как текст, но разность считайте в секундах.', '{"func": "command_timelines", "tests": [{"args": [["10:00:05 INFO engine c1 Running command", "10:00:07 INFO vdsm c1 create", "10:00:09 ERROR libvirt c1 internal error", "10:00:09 ERROR vdsm c1 failed", "10:00:01 INFO engine c2 other", "10:00:02 INFO engine - no corr", "bad line", "xx:00:02 INFO engine c3 bad time", "10:00:12 ERROR engine c1 command failed", "10:00:03 WARN vdsm c2"]], "expected": {"c1": {"start": "10:00:05", "end": "10:00:12", "duration": 7, "errors": 3, "sources": ["engine", "libvirt", "vdsm"]}, "c2": {"start": "10:00:01", "end": "10:00:03", "duration": 2, "errors": 0, "sources": ["engine", "vdsm"]}}}, {"args": [[]], "expected": {}}, {"args": [["10:00:00 INFO engine -"]], "expected": {}}, {"args": [["10:00:00 INFO engine a", "09:59:58 ERROR vdsm a"]], "expected": {"a": {"start": "09:59:58", "end": "10:00:00", "duration": 2, "errors": 1, "sources": ["engine", "vdsm"]}}}, {"args": [["10:00:00 INFO engine a", "10:00:00 INFO engine a"]], "expected": {"a": {"start": "10:00:00", "end": "10:00:00", "duration": 0, "errors": 0, "sources": ["engine"]}}}, {"args": [["1:00:00 INFO engine a", "10:00 INFO engine a", "10:00:00 INFO engine"]], "expected": {}}, {"args": [["23:59:59 ERROR qemu z boom", "00:00:01 INFO engine y"]], "expected": {"z": {"start": "23:59:59", "end": "23:59:59", "duration": 0, "errors": 1, "sources": ["qemu"]}, "y": {"start": "00:00:01", "end": "00:00:01", "duration": 0, "errors": 0, "sources": ["engine"]}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-first-error', 5, 'func', 'Первая ошибка в цепочке', 'Слои от верхнего к нижнему: engine (глубина 0), vdsm (1), libvirt (2), qemu (3), sanlock (4). Дан список строк журналов lines — кортежи (время "ЧЧ:ММ:СС", источник, уровень, corr, сообщение) в произвольном порядке, идентификатор корреляции corr и словарь skew: источник → на сколько секунд его часы убегают вперёд (если источника нет в словаре, то на 0). Истинное время строки равно её времени минус поправка источника (в секундах от полуночи; результат может быть отрицательным). Напишите функцию first_error(lines, corr, skew): среди строк с уровнем ERROR и данным corr найдите ту, у которой истинное время наименьшее; при равенстве берите источник с большей глубиной, а при равенстве и этого — строку, стоящую в списке раньше. Верните кортеж (источник, сообщение) или None, если ошибок нет.', 'def first_error(lines, corr, skew):
    pass
', 'Для каждой подходящей строки постройте ключ (истинное время, −глубина, индекс) и возьмите минимальный. Время переведите в секунды.', '{"func": "first_error", "tests": [{"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}, {"__tuple__": ["10:00:07", "qemu", "WARN", "c1", "slow"]}, {"__tuple__": ["10:00:01", "qemu", "ERROR", "c2", "other"]}], "c1", {}], "expected": {"__tuple__": ["sanlock", "lease timeout"]}}, {"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}, {"__tuple__": ["10:00:07", "qemu", "WARN", "c1", "slow"]}, {"__tuple__": ["10:00:01", "qemu", "ERROR", "c2", "other"]}], "c2", {}], "expected": {"__tuple__": ["qemu", "other"]}}, {"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}, {"__tuple__": ["10:00:07", "qemu", "WARN", "c1", "slow"]}, {"__tuple__": ["10:00:01", "qemu", "ERROR", "c2", "other"]}], "c9", {}], "expected": null}, {"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}, {"__tuple__": ["10:00:07", "qemu", "WARN", "c1", "slow"]}, {"__tuple__": ["10:00:01", "qemu", "ERROR", "c2", "other"]}], "c1", {"vdsm": 5}], "expected": {"__tuple__": ["vdsm", "Create failed"]}}, {"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}], "c1", {"sanlock": -5}], "expected": {"__tuple__": ["libvirt", "Cannot access storage"]}}, {"args": [[{"__tuple__": ["10:00:12", "engine", "ERROR", "c1", "Command failed"]}, {"__tuple__": ["10:00:09", "vdsm", "ERROR", "c1", "Create failed"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "Cannot access storage"]}, {"__tuple__": ["10:00:08", "sanlock", "ERROR", "c1", "lease timeout"]}], "c1", {"engine": 10}], "expected": {"__tuple__": ["engine", "Command failed"]}}, {"args": [[{"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "a"]}, {"__tuple__": ["10:00:08", "libvirt", "ERROR", "c1", "b"]}], "c1", {}], "expected": {"__tuple__": ["libvirt", "a"]}}, {"args": [[{"__tuple__": ["10:00:08", "qemu", "WARN", "c1", "a"]}], "c1", {}], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-triage', 6, 'func', 'Триаж по симптомам', 'Каждый симптом добавляет очки слоям. Слои в порядке приоритета: engine, vdsm, libvirt, qemu, storage, network. Таблица: login_fails: engine +3; portal_slow: engine +2; no_heartbeat: vdsm +3, network +2; vm_wont_start: libvirt +2, qemu +2, storage +1; vm_crashed: qemu +3, libvirt +1; domain_inactive: storage +3, network +1; disk_io_errors: storage +3, qemu +1; migration_fails: network +2, libvirt +1, qemu +1; cert_error: engine +2, vdsm +2; ping_ok: network −3; many_hosts_affected: storage +2, network +1, engine +1. Напишите функцию triage(symptoms): symptoms — список названий симптомов. Повторы считаются один раз, неизвестные названия игнорируются. Верните кортеж (слой, очки) для слоя с наибольшей суммой; при равенстве побеждает слой, стоящий раньше в списке приоритета. Если наибольшая сумма не больше нуля, верните ("unknown", 0).', 'def triage(symptoms):
    pass
', 'Положите таблицу в словарь словарей, обходите set(symptoms). Для максимума идите по слоям в порядке приоритета и заменяйте лучший только при строгом превосходстве.', '{"func": "triage", "tests": [{"args": [[]], "expected": {"__tuple__": ["unknown", 0]}}, {"args": [["login_fails"]], "expected": {"__tuple__": ["engine", 3]}}, {"args": [["no_heartbeat", "ping_ok"]], "expected": {"__tuple__": ["vdsm", 3]}}, {"args": [["vm_wont_start", "disk_io_errors", "many_hosts_affected"]], "expected": {"__tuple__": ["storage", 6]}}, {"args": [["domain_inactive", "many_hosts_affected", "ping_ok"]], "expected": {"__tuple__": ["storage", 5]}}, {"args": [["ping_ok"]], "expected": {"__tuple__": ["unknown", 0]}}, {"args": [["login_fails", "login_fails", "portal_slow"]], "expected": {"__tuple__": ["engine", 5]}}, {"args": [["unknown_thing", "cert_error"]], "expected": {"__tuple__": ["engine", 2]}}, {"args": [["vm_wont_start"]], "expected": {"__tuple__": ["libvirt", 2]}}, {"args": [["migration_fails"]], "expected": {"__tuple__": ["network", 2]}}, {"args": [["vm_crashed", "vm_wont_start"]], "expected": {"__tuple__": ["qemu", 5]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-capacity-days', 7, 'func', 'Дни до исчерпания памяти', 'Планировщик ёмкости. host_gb — память хостов кластера в ГБ, used_gb — суммарная память виртуальных машин по дням (последнее значение — сегодня). Запас по правилу N+1: полезная ёмкость равна сумме памяти всех хостов минус память самого большого хоста (для пустого списка хостов — 0). Напишите функцию capacity_days(host_gb, used_gb). Если used_gb пуст, верните None. Свободно = полезная ёмкость минус последнее значение used_gb; если свободно не больше нуля, верните 0. Если в used_gb меньше двух значений, верните None. Прирост за день — (последнее минус первое) делить на (число значений минус один); если общий прирост (последнее минус первое) не положителен, верните None (ресурс не кончится). Иначе верните целое число полных дней до исчерпания: свободно, делённое на прирост за день, с округлением вниз. Считайте в целых числах, как свободно * (n − 1) // (последнее − первое).', 'def capacity_days(host_gb, used_gb):
    pass
', 'Порядок проверок важен: пусто → None; free <= 0 → 0; меньше двух значений → None; нет роста → None; иначе целочисленная формула.', '{"func": "capacity_days", "tests": [{"args": [[64, 64, 64], [100, 110, 120, 130]], "expected": 0}, {"args": [[64, 64, 64], [100, 100, 100]], "expected": null}, {"args": [[64, 64], [70, 71]], "expected": 0}, {"args": [[64, 64, 64], []], "expected": null}, {"args": [[64], [10, 20]], "expected": 0}, {"args": [[], [1, 2]], "expected": 0}, {"args": [[64, 64, 64], [60, 70, 80, 90, 100]], "expected": 2}, {"args": [[128, 64, 64], [10, 20, 30, 31]], "expected": 13}, {"args": [[64, 64, 64], [50]], "expected": null}, {"args": [[64, 64, 64], [200, 210]], "expected": 0}, {"args": [[128, 64, 64], [0, 3]], "expected": 41}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-check-certs', 8, 'func', 'Сроки сертификатов и часы', 'Менеджер и хост видят время по-разному: часы менеджера показывают now (секунды), часы хоста — now + offset (offset может быть отрицательным). certs — словарь имя → кортеж (not_before, not_after). Сертификат проверяется по обоим часам: пусть lo — меньшее из двух значений времени, hi — большее. Статус сертификата: "not_yet_valid", если lo < not_before; иначе "expired", если hi >= not_after; иначе "expiring", если not_after − hi <= warn; иначе всё в порядке. Напишите функцию check_certs(certs, now, offset, warn): верните отсортированный список кортежей (имя, статус) для сертификатов не в порядке. Кроме того, если abs(offset) > 300, добавьте в список кортеж ("clock", "skewed"). Сортируйте полученные кортежи как есть. Имени "clock" в certs нет.', 'def check_certs(certs, now, offset, warn):
    pass
', 'Вычислите lo и hi один раз, потом проверяйте по порядку: not_yet_valid, expired, expiring. В конце добавьте clock и вызовите sorted.', '{"func": "check_certs", "tests": [{"args": [{"api": {"__tuple__": [100, 1000]}, "vdsm": {"__tuple__": [100, 500]}, "future": {"__tuple__": [600, 2000]}, "soon": {"__tuple__": [0, 560]}}, 400, 0, 100], "expected": [{"__tuple__": ["future", "not_yet_valid"]}, {"__tuple__": ["vdsm", "expiring"]}]}, {"args": [{"api": {"__tuple__": [100, 1000]}, "vdsm": {"__tuple__": [100, 500]}, "future": {"__tuple__": [600, 2000]}, "soon": {"__tuple__": [0, 560]}}, 400, 200, 100], "expected": [{"__tuple__": ["future", "not_yet_valid"]}, {"__tuple__": ["soon", "expired"]}, {"__tuple__": ["vdsm", "expired"]}]}, {"args": [{"api": {"__tuple__": [100, 1000]}, "vdsm": {"__tuple__": [100, 500]}, "future": {"__tuple__": [600, 2000]}, "soon": {"__tuple__": [0, 560]}}, 400, -300, 100], "expected": [{"__tuple__": ["future", "not_yet_valid"]}, {"__tuple__": ["vdsm", "expiring"]}]}, {"args": [{"api": {"__tuple__": [100, 1000]}, "vdsm": {"__tuple__": [100, 500]}, "future": {"__tuple__": [600, 2000]}, "soon": {"__tuple__": [0, 560]}}, 400, -301, 10], "expected": [{"__tuple__": ["api", "not_yet_valid"]}, {"__tuple__": ["clock", "skewed"]}, {"__tuple__": ["future", "not_yet_valid"]}, {"__tuple__": ["vdsm", "not_yet_valid"]}]}, {"args": [{}, 0, 0, 0], "expected": []}, {"args": [{}, 0, 301, 0], "expected": [{"__tuple__": ["clock", "skewed"]}]}, {"args": [{"a": {"__tuple__": [0, 100]}}, 100, 0, 0], "expected": [{"__tuple__": ["a", "expired"]}]}, {"args": [{"a": {"__tuple__": [0, 100]}}, 99, 0, 1], "expected": [{"__tuple__": ["a", "expiring"]}]}, {"args": [{"a": {"__tuple__": [0, 100]}}, 99, 0, 0], "expected": []}, {"args": [{"a": {"__tuple__": [10, 100]}}, 10, -1, 0], "expected": [{"__tuple__": ["a", "not_yet_valid"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-host-status', 9, 'func', 'Статус хоста', 'Упрощённая модель статуса хоста. host — словарь с полями maintenance (bool), heartbeat (bool), nets (список логических сетей, настроенных на хосте) и seen (список доменов хранилища, которые хост видит). required_nets — сети, обязательные для кластера, attached_domains — домены, подключённые к центру данных. Напишите функцию host_status(host, required_nets, attached_domains): верните кортеж (статус, причины). Если maintenance — ("Maintenance", []). Иначе если нет heartbeat — ("NonResponsive", []). Иначе соберите причины: для каждой отсутствующей на хосте обязательной сети "net:имя" (по алфавиту), затем для каждого невидимого домена "sd:имя" (по алфавиту); если причины есть — ("NonOperational", причины), иначе ("Up", []).', 'def host_status(host, required_nets, attached_domains):
    pass
', 'Разность множеств даёт недостающие элементы: set(required_nets) - set(host[''nets'']). Проверки идут в порядке приоритета.', '{"func": "host_status", "tests": [{"args": [{"maintenance": false, "heartbeat": true, "nets": ["ovirtmgmt", "vm"], "seen": ["d1", "d2"]}, ["ovirtmgmt", "vm"], ["d1", "d2"]], "expected": {"__tuple__": ["Up", []]}}, {"args": [{"maintenance": true, "heartbeat": false, "nets": ["ovirtmgmt", "vm"], "seen": ["d1", "d2"]}, ["x"], ["y"]], "expected": {"__tuple__": ["Maintenance", []]}}, {"args": [{"maintenance": false, "heartbeat": false, "nets": ["ovirtmgmt", "vm"], "seen": ["d1", "d2"]}, [], []], "expected": {"__tuple__": ["NonResponsive", []]}}, {"args": [{"maintenance": false, "heartbeat": true, "nets": ["ovirtmgmt"], "seen": ["d1", "d2"]}, ["ovirtmgmt", "vm"], ["d1"]], "expected": {"__tuple__": ["NonOperational", ["net:vm"]]}}, {"args": [{"maintenance": false, "heartbeat": true, "nets": ["ovirtmgmt", "vm"], "seen": ["d1"]}, ["vm"], ["d2", "d1", "d0"]], "expected": {"__tuple__": ["NonOperational", ["sd:d0", "sd:d2"]]}}, {"args": [{"maintenance": false, "heartbeat": true, "nets": ["z", "ovirtmgmt", "vm"], "seen": ["d1", "d2"]}, ["vm", "b", "a"], []], "expected": {"__tuple__": ["NonOperational", ["net:a", "net:b"]]}}, {"args": [{"maintenance": false, "heartbeat": true, "nets": [], "seen": []}, ["n"], ["d"]], "expected": {"__tuple__": ["NonOperational", ["net:n", "sd:d"]]}}, {"args": [{"maintenance": false, "heartbeat": true, "nets": ["ovirtmgmt", "vm"], "seen": ["d1", "d2"]}, [], []], "expected": {"__tuple__": ["Up", []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-domain-status', 10, 'func', 'Состояние домена хранилища', 'Менеджер судит о домене хранилища по отчётам хостов. reports — словарь хост → "ok" или "fail" (может ли хост работать с доменом), host_states — словарь хост → статус хоста. В расчёт идут только хосты, которые есть в обоих словарях и имеют статус "Up". Напишите функцию domain_status(reports, host_states): верните кортеж (состояние, хосты). Если ни одного учитываемого хоста нет — ("Unknown", []). Если у всех учитываемых хостов "fail" — ("Inactive", []). Иначе — ("Active", отсортированный список учитываемых хостов с "fail": им нужно перейти в NonOperational).', 'def domain_status(reports, host_states):
    pass
', 'Сначала отфильтруйте отчёты по host_states.get(host) == ''Up'', потом сравните число сбойных хостов с числом учитываемых.', '{"func": "domain_status", "tests": [{"args": [{"h1": "ok", "h2": "ok"}, {"h1": "Up", "h2": "Up"}], "expected": {"__tuple__": ["Active", []]}}, {"args": [{"h1": "fail", "h2": "fail"}, {"h1": "Up", "h2": "Up"}], "expected": {"__tuple__": ["Inactive", []]}}, {"args": [{"h1": "ok", "h2": "fail", "h3": "fail"}, {"h1": "Up", "h2": "Up", "h3": "Up"}], "expected": {"__tuple__": ["Active", ["h2", "h3"]]}}, {"args": [{"h1": "fail"}, {"h1": "Maintenance"}], "expected": {"__tuple__": ["Unknown", []]}}, {"args": [{}, {}], "expected": {"__tuple__": ["Unknown", []]}}, {"args": [{"h1": "ok", "h2": "fail"}, {"h1": "Up", "h2": "NonResponsive"}], "expected": {"__tuple__": ["Active", []]}}, {"args": [{"h1": "ok", "hx": "fail"}, {"h1": "Up"}], "expected": {"__tuple__": ["Active", []]}}, {"args": [{"h2": "fail", "h1": "fail", "h3": "ok"}, {"h1": "Up", "h2": "Up", "h3": "Up"}], "expected": {"__tuple__": ["Active", ["h1", "h2"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-stale-locks', 11, 'func', 'Зависшие блокировки образов', 'Блокировки образов держат задачи. events — список кортежей (вид, образ, задача) в порядке событий. Вид "lock": если образ ещё не заблокирован, его блокирует эта задача; если уже заблокирован (кем угодно), событие игнорируется. Вид "unlock": если образ заблокирован именно этой задачей, блокировка снимается; иначе событие игнорируется. running — список задач, которые ещё выполняются. Напишите функцию stale_locks(events, running): верните отсортированный список кортежей (образ, задача) для образов, которые в конце всё ещё заблокированы задачей, отсутствующей в running (это и есть «зависший» Image Locked).', 'def stale_locks(events, running):
    pass
', 'Храните словарь образ → задача. После обработки всех событий отфильтруйте записи, у которых задача не входит в running, и отсортируйте.', '{"func": "stale_locks", "tests": [{"args": [[{"__tuple__": ["lock", "img1", "t1"]}, {"__tuple__": ["lock", "img2", "t2"]}, {"__tuple__": ["unlock", "img1", "t1"]}, {"__tuple__": ["lock", "img3", "t3"]}], ["t3"]], "expected": [{"__tuple__": ["img2", "t2"]}]}, {"args": [[{"__tuple__": ["lock", "img1", "t1"]}, {"__tuple__": ["lock", "img2", "t2"]}, {"__tuple__": ["unlock", "img1", "t1"]}, {"__tuple__": ["lock", "img3", "t3"]}], []], "expected": [{"__tuple__": ["img2", "t2"]}, {"__tuple__": ["img3", "t3"]}]}, {"args": [[], []], "expected": []}, {"args": [[{"__tuple__": ["lock", "a", "t1"]}, {"__tuple__": ["lock", "a", "t2"]}, {"__tuple__": ["unlock", "a", "t2"]}], ["t2"]], "expected": [{"__tuple__": ["a", "t1"]}]}, {"args": [[{"__tuple__": ["lock", "a", "t1"]}, {"__tuple__": ["lock", "a", "t2"]}, {"__tuple__": ["unlock", "a", "t2"]}], ["t1"]], "expected": []}, {"args": [[{"__tuple__": ["lock", "a", "t1"]}, {"__tuple__": ["unlock", "a", "t1"]}, {"__tuple__": ["lock", "a", "t2"]}], []], "expected": [{"__tuple__": ["a", "t2"]}]}, {"args": [[{"__tuple__": ["unlock", "a", "t1"]}, {"__tuple__": ["lock", "b", "t1"]}, {"__tuple__": ["lock", "a", "t3"]}], ["t1"]], "expected": [{"__tuple__": ["a", "t3"]}]}, {"args": [[{"__tuple__": ["lock", "z", "t9"]}, {"__tuple__": ["lock", "a", "t9"]}, {"__tuple__": ["lock", "m", "t1"]}], ["t1"]], "expected": [{"__tuple__": ["a", "t9"]}, {"__tuple__": ["z", "t9"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-live-merge', 12, 'func', 'Живое слияние снимка и сбой', 'Модель живого слияния снимка. chain — список томов от базового до активного, victim — том, который сливается вниз в предыдущий том цепочки, fail_step — шаг, на котором произошёл сбой, или None. Шаги по порядку: "extend", "commit", "pivot", "cleanup". Напишите функцию live_merge(chain, victim, fail_step): верните кортеж (цепочка, осиротевшие, статус). Если victim нет в цепочке или он базовый (первый), слияние отклонено: (копия цепочки, [], "rejected"). Иначе, если сбой на "extend" или "commit" — цепочка не изменилась: (копия цепочки, [], "rolled_back"). Сбой на "pivot" — цепочка не изменилась, но слияние можно повторить: (копия цепочки, [], "retry"). Сбой на "cleanup" — слияние выполнено, но том остался на диске: (цепочка без victim, [victim], "partial"). Без сбоя — (цепочка без victim, [], "ok"). Исходный список менять нельзя.', 'def live_merge(chain, victim, fail_step):
    pass
', 'Сначала проверка rejected, потом вычислите цепочку без victim и разберите fail_step. Возвращайте list(chain), а не сам chain.', '{"func": "live_merge", "tests": [{"args": [["base", "s1", "s2", "active"], "s1", null], "expected": {"__tuple__": [["base", "s2", "active"], [], "ok"]}}, {"args": [["base", "s1", "s2", "active"], "active", null], "expected": {"__tuple__": [["base", "s1", "s2"], [], "ok"]}}, {"args": [["base", "s1", "s2", "active"], "base", null], "expected": {"__tuple__": [["base", "s1", "s2", "active"], [], "rejected"]}}, {"args": [["base", "s1", "s2", "active"], "zz", "commit"], "expected": {"__tuple__": [["base", "s1", "s2", "active"], [], "rejected"]}}, {"args": [["base", "s1", "s2", "active"], "s2", "extend"], "expected": {"__tuple__": [["base", "s1", "s2", "active"], [], "rolled_back"]}}, {"args": [["base", "s1", "s2", "active"], "s2", "commit"], "expected": {"__tuple__": [["base", "s1", "s2", "active"], [], "rolled_back"]}}, {"args": [["base", "s1", "s2", "active"], "s2", "pivot"], "expected": {"__tuple__": [["base", "s1", "s2", "active"], [], "retry"]}}, {"args": [["base", "s1", "s2", "active"], "s2", "cleanup"], "expected": {"__tuple__": [["base", "s1", "active"], ["s2"], "partial"]}}, {"args": [["only"], "only", null], "expected": {"__tuple__": [["only"], [], "rejected"]}}, {"args": [["b", "a"], "a", "cleanup"], "expected": {"__tuple__": [["b"], ["a"], "partial"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-alert-windows', 13, 'func', 'Окна срабатывания оповещения', 'Оповещение срабатывает, когда метрика держится выше порога достаточно долго. samples — список значений метрики по минутам; значение None означает пропущенный замер. Напишите функцию alert_windows(samples, threshold, min_len): верните список кортежей (первый индекс, последний индекс) для каждой серии подряд идущих замеров строго выше threshold, в которой не менее min_len таких замеров. Пропущенный замер (None) не прерывает серию и не считается замером, а в границы серии не входит, если стоит с краю. Замер, не превышающий порог, серию завершает. Серии возвращайте по возрастанию индексов.', 'def alert_windows(samples, threshold, min_len):
    pass
', 'Храните начало серии, индекс последнего «горячего» замера и счётчик. На None просто продолжайте; на холодном замере и в конце закройте серию, проверив счётчик.', '{"func": "alert_windows", "tests": [{"args": [[1, 2, 9, 9, 1, 9, 9, 9], 5, 2], "expected": [{"__tuple__": [2, 3]}, {"__tuple__": [5, 7]}]}, {"args": [[9, 9, 9], 5, 3], "expected": [{"__tuple__": [0, 2]}]}, {"args": [[9, 9, 9], 5, 4], "expected": []}, {"args": [[1, 2, 3], 5, 1], "expected": []}, {"args": [[], 5, 1], "expected": []}, {"args": [[9, null, 9, 1, 9], 5, 3], "expected": []}, {"args": [[9, 9, null, null, 1], 5, 2], "expected": [{"__tuple__": [0, 1]}]}, {"args": [[9, 9, null, null, 9], 5, 3], "expected": [{"__tuple__": [0, 4]}]}, {"args": [[5, 5, 5], 5, 1], "expected": []}, {"args": [[9, 1, 9, 9], 5, 2], "expected": [{"__tuple__": [2, 3]}]}, {"args": [[null, 9, 9, null], 5, 2], "expected": [{"__tuple__": [1, 2]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-overcommit', 14, 'func', 'Проверка переподписки памяти', 'host_gb — физическая память хостов кластера в ГБ, vm_gb — память, выделенная виртуальным машинам, limit_pct — допустимая переподписка в процентах (100 — без переподписки). Напишите функцию overcommit_check(host_gb, vm_gb, limit_pct): пусть H — сумма host_gb, V — сумма vm_gb. Если H равно 0, верните (0, "over", False). Иначе верните кортеж из трёх значений: ratio — целая часть от 100 * V / H; verdict — "ok", если V * 100 <= limit_pct * H, иначе "over" (сравнение точное, в целых числах, не по округлённому ratio); n1 — True, если V * 100 <= limit_pct * (H минус память самого большого хоста), то есть нагрузка укладывается в лимит и после потери самого большого хоста.', 'def overcommit_check(host_gb, vm_gb, limit_pct):
    pass
', 'Всё считается целыми числами: ratio = 100 * V // H; для вердикта и n1 сравнивайте V * 100 с limit_pct * (...).', '{"func": "overcommit_check", "tests": [{"args": [[64, 64, 64], [100, 50], 150], "expected": {"__tuple__": [78, "ok", true]}}, {"args": [[64, 64, 64], [100, 100], 100], "expected": {"__tuple__": [104, "over", false]}}, {"args": [[64, 64, 64], [130], 100], "expected": {"__tuple__": [67, "ok", false]}}, {"args": [[64, 64], [64, 64], 100], "expected": {"__tuple__": [100, "ok", false]}}, {"args": [[64, 64], [], 100], "expected": {"__tuple__": [0, "ok", true]}}, {"args": [[], [1], 100], "expected": {"__tuple__": [0, "over", false]}}, {"args": [[128, 64, 64], [100, 100], 100], "expected": {"__tuple__": [78, "ok", false]}}, {"args": [[100], [150], 200], "expected": {"__tuple__": [150, "ok", false]}}, {"args": [[100, 50], [100], 70], "expected": {"__tuple__": [66, "ok", false]}}, {"args": [[100, 100, 100], [100, 100], 100], "expected": {"__tuple__": [66, "ok", true]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ov25-effective-perms', 15, 'func', 'Эффективные права', 'Права в oVirt выдаются ролями на объектах. roles — словарь роль → список прав. assignments — список кортежей (субъект, роль, объект), где субъект — имя пользователя или группы. path — список объектов от системы до виртуальной машины, например ["system", "dc1", "cl1", "vm1"]: назначение на любой объект из пути действует на машину (права наследуются вниз). Напишите функцию effective_perms(user, groups, assignments, path, roles): верните отсортированный список без повторов всех прав, которые получает пользователь user, состоящий в группах groups, на машину с данным path: берутся назначения, где субъект — сам пользователь или одна из его групп, а объект входит в path. Роль, которой нет в roles, не даёт ничего.', 'def effective_perms(user, groups, assignments, path, roles):
    pass
', 'Соберите множество субъектов {user} | set(groups) и объединяйте права ролей подходящих назначений через |=.', '{"func": "effective_perms", "tests": [{"args": ["alice", ["ops"], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": ["vm.start", "vm.stop", "vm.view"]}, {"args": ["alice", [], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": ["vm.start", "vm.stop", "vm.view"]}, {"args": ["bob", ["devs"], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": ["vm.start", "vm.stop", "vm.view"]}, {"args": ["carol", [], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": []}, {"args": ["alice", ["ops", "devs"], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}], ["system", "dc2", "cl9", "vm2"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": ["host.edit", "vm.delete", "vm.edit", "vm.start", "vm.stop", "vm.view"]}, {"args": ["alice", [], [], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": []}, {"args": ["alice", [], [{"__tuple__": ["alice", "empty", "vm1"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": []}, {"args": ["dave", ["ops"], [{"__tuple__": ["alice", "operator", "vm1"]}, {"__tuple__": ["ops", "viewer", "cl1"]}, {"__tuple__": ["bob", "admin", "dc2"]}, {"__tuple__": ["alice", "admin", "cl9"]}, {"__tuple__": ["ops", "admin", "vm2"]}, {"__tuple__": ["alice", "ghost", "system"]}, {"__tuple__": ["devs", "operator", "system"]}, {"__tuple__": ["ops", "admin", "cl1"]}], ["system", "dc1", "cl1", "vm1"], {"viewer": ["vm.view"], "operator": ["vm.view", "vm.start", "vm.stop"], "admin": ["vm.view", "vm.edit", "vm.delete", "host.edit"], "empty": []}], "expected": ["host.ed