INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 25, 'ovb25-heal', 16, 'stdout', 'Автоматическая починка', 'Обойдите схему как при диагностике: менеджер должен сидеть в каждой сети с ролью management (engine → сеть); домен, не подключённый ни к какому дата-центру, подключите к единственному дата-центру; сеть, которой нет ни у одного кластера, подключите ко всем кластерам её дата-центра; и каждому хосту дайте все сети его кластера и все домены его дата-центра. Схема — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Напишите fix(board) и верните {"add": [[from, to], ...], "remove": [[from, to], ...]} — какие связи добавить и какие убрать (объекты менять нельзя). Проверка запускает вашу функцию на четырёх разных схемах (захардкодить ответ не выйдет), показывает каждую получившуюся схему на доске со статусами и целями сценария, а решение принимается, когда на всех четырёх выполнены все цели. Те же сценарии можно решить руками на досках соответствующих упражнений.', 'def fix(board):
    # return {"add": [[from_id, to_id], ...], "remove": [[from_id, to_id], ...]}
    return {"add": [], "remove": []}
', 'Это три предыдущие задачи в одной: сначала связи менеджера, домена и сети с верхнего уровня, потом цикл по хостам. Роль сети лежит в params.role (по умолчанию vm).', '{"driver": "import json as _json\nimport copy as _copy\n_BOARDS = _json.loads(r\"\"\"[{\"edges\":[{\"from\":\"engine\",\"to\":\"dc1\"},{\"from\":\"dc1\",\"to\":\"cl1\"},{\"from\":\"cl1\",\"to\":\"h1\"},{\"from\":\"cl1\",\"to\":\"h2\"},{\"from\":\"dc1\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"cl1\"},{\"from\":\"mgmt\",\"to\":\"h1\"},{\"from\":\"mgmt\",\"to\":\"h2\"},{\"from\":\"dc1\",\"to\":\"vmnet\"},{\"from\":\"dc1\",\"to\":\"nfs\"},{\"from\":\"nfs\",\"to\":\"h1\"},{\"from\":\"nfs\",\"to\":\"h2\"},{\"from\":\"h1\",\"to\":\"vm1\"},{\"from\":\"vmnet\",\"to\":\"vm1\"},{\"from\":\"nfs2\",\"to\":\"vm1\"}],\"nodes\":[{\"id\":\"engine\",\"kind\":\"engine\",\"name\":\"engine\"},{\"id\":\"dc1\",\"kind\":\"data_center\",\"name\":\"Default\"},{\"id\":\"cl1\",\"kind\":\"cluster\",\"name\":\"cluster-a\"},{\"id\":\"h1\",\"kind\":\"host\",\"name\":\"host-1\"},{\"id\":\"h2\",\"kind\":\"host\",\"name\":\"host-2\"},{\"id\":\"mgmt\",\"kind\":\"network\",\"name\":\"ovirtmgmt\",\"params\":{\"required\":true,\"role\":\"management\"}},{\"id\":\"vmnet\",\"kind\":\"network\",\"name\":\"vm-net\",\"params\":{\"required\":false,\"role\":\"vm\"}},{\"id\":\"nfs\",\"kind\":\"storage_domain\",\"name\":\"nfs-data\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"nfs2\",\"kind\":\"storage_domain\",\"name\":\"nfs-vms\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"vm1\",\"kind\":\"vm\",\"name\":\"web-1\"}]},{\"edges\":[{\"from\":\"engine\",\"to\":\"dc1\"},{\"from\":\"dc1\",\"to\":\"cl1\"},{\"from\":\"cl1\",\"to\":\"h1\"},{\"from\":\"cl1\",\"to\":\"h2\"},{\"from\":\"cl1\",\"to\":\"h3\"},{\"from\":\"dc1\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"cl1\"},{\"from\":\"engine\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"h1\"},{\"from\":\"mgmt\",\"to\":\"h3\"},{\"from\":\"dc1\",\"to\":\"vmnet\"},{\"from\":\"vmnet\",\"to\":\"cl1\"},{\"from\":\"vmnet\",\"to\":\"h2\"},{\"from\":\"vmnet\",\"to\":\"h3\"},{\"from\":\"dc1\",\"to\":\"nfs\"},{\"from\":\"nfs\",\"to\":\"h1\"},{\"from\":\"nfs\",\"to\":\"h2\"},{\"from\":\"nfs\",\"to\":\"h3\"},{\"from\":\"h1\",\"to\":\"vm1\"},{\"from\":\"vmnet\",\"to\":\"vm1\"},{\"from\":\"nfs\",\"to\":\"vm1\"}],\"nodes\":[{\"id\":\"engine\",\"kind\":\"engine\",\"name\":\"engine\"},{\"id\":\"dc1\",\"kind\":\"data_center\",\"name\":\"Default\"},{\"id\":\"cl1\",\"kind\":\"cluster\",\"name\":\"cluster-a\"},{\"id\":\"h1\",\"kind\":\"host\",\"name\":\"host-1\"},{\"id\":\"h2\",\"kind\":\"host\",\"name\":\"host-2\"},{\"id\":\"h3\",\"kind\":\"host\",\"name\":\"host-3\"},{\"id\":\"mgmt\",\"kind\":\"network\",\"name\":\"ovirtmgmt\",\"params\":{\"required\":true,\"role\":\"management\"}},{\"id\":\"vmnet\",\"kind\":\"network\",\"name\":\"vm-net\",\"params\":{\"required\":false,\"role\":\"vm\"}},{\"id\":\"nfs\",\"kind\":\"storage_domain\",\"name\":\"nfs-data\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"vm1\",\"kind\":\"vm\",\"name\":\"web-1\"}]},{\"edges\":[{\"from\":\"engine\",\"to\":\"dc1\"},{\"from\":\"dc1\",\"to\":\"cl1\"},{\"from\":\"cl1\",\"to\":\"h1\"},{\"from\":\"cl1\",\"to\":\"h2\"},{\"from\":\"dc1\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"cl1\"},{\"from\":\"engine\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"h1\"},{\"from\":\"mgmt\",\"to\":\"h2\"},{\"from\":\"dc1\",\"to\":\"backup\"},{\"from\":\"backup\",\"to\":\"cl1\"},{\"from\":\"backup\",\"to\":\"h1\"},{\"from\":\"h1\",\"to\":\"vm1\"},{\"from\":\"nfs\",\"to\":\"vm1\"}],\"nodes\":[{\"id\":\"engine\",\"kind\":\"engine\",\"name\":\"engine\"},{\"id\":\"dc1\",\"kind\":\"data_center\",\"name\":\"Default\"},{\"id\":\"cl1\",\"kind\":\"cluster\",\"name\":\"cluster-a\"},{\"id\":\"h1\",\"kind\":\"host\",\"name\":\"host-1\"},{\"id\":\"h2\",\"kind\":\"host\",\"name\":\"host-2\"},{\"id\":\"mgmt\",\"kind\":\"network\",\"name\":\"ovirtmgmt\",\"params\":{\"required\":true,\"role\":\"management\"}},{\"id\":\"backup\",\"kind\":\"network\",\"name\":\"backup\",\"params\":{\"required\":true,\"role\":\"vm\"}},{\"id\":\"nfs\",\"kind\":\"storage_domain\",\"name\":\"nfs-data\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"vm1\",\"kind\":\"vm\",\"name\":\"web-1\"}]},{\"edges\":[{\"from\":\"engine\",\"to\":\"dc1\"},{\"from\":\"dc1\",\"to\":\"cl1\"},{\"from\":\"dc1\",\"to\":\"cl2\"},{\"from\":\"cl1\",\"to\":\"h1\"},{\"from\":\"cl1\",\"to\":\"h2\"},{\"from\":\"cl2\",\"to\":\"h3\"},{\"from\":\"cl2\",\"to\":\"h4\"},{\"from\":\"dc1\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"cl1\"},{\"from\":\"mgmt\",\"to\":\"cl2\"},{\"from\":\"engine\",\"to\":\"mgmt\"},{\"from\":\"mgmt\",\"to\":\"h1\"},{\"from\":\"mgmt\",\"to\":\"h2\"},{\"from\":\"mgmt\",\"to\":\"h3\"},{\"from\":\"mgmt\",\"to\":\"h4\"},{\"from\":\"dc1\",\"to\":\"backup\"},{\"from\":\"backup\",\"to\":\"cl2\"},{\"from\":\"backup\",\"to\":\"h3\"},{\"from\":\"dc1\",\"to\":\"dbnet\"},{\"from\":\"dbnet\",\"to\":\"cl2\"},{\"from\":\"dbnet\",\"to\":\"h4\"},{\"from\":\"dc1\",\"to\":\"nfs\"},{\"from\":\"nfs\",\"to\":\"h1\"},{\"from\":\"nfs\",\"to\":\"h2\"},{\"from\":\"nfs\",\"to\":\"h3\"},{\"from\":\"nfs\",\"to\":\"h4\"},{\"from\":\"dc1\",\"to\":\"fast\"},{\"from\":\"fast\",\"to\":\"h1\"},{\"from\":\"fast\",\"to\":\"h3\"},{\"from\":\"fast\",\"to\":\"h4\"},{\"from\":\"h1\",\"to\":\"vm1\"},{\"from\":\"nfs\",\"to\":\"vm1\"},{\"from\":\"h3\",\"to\":\"vm2\"},{\"from\":\"dbnet\",\"to\":\"vm2\"},{\"from\":\"fast\",\"to\":\"vm2\"}],\"nodes\":[{\"id\":\"engine\",\"kind\":\"engine\",\"name\":\"engine\"},{\"id\":\"dc1\",\"kind\":\"data_center\",\"name\":\"Default\"},{\"id\":\"cl1\",\"kind\":\"cluster\",\"name\":\"cluster-a\"},{\"id\":\"cl2\",\"kind\":\"cluster\",\"name\":\"cluster-b\"},{\"id\":\"h1\",\"kind\":\"host\",\"name\":\"host-1\"},{\"id\":\"h2\",\"kind\":\"host\",\"name\":\"host-2\"},{\"id\":\"h3\",\"kind\":\"host\",\"name\":\"host-3\"},{\"id\":\"h4\",\"kind\":\"host\",\"name\":\"host-4\"},{\"id\":\"mgmt\",\"kind\":\"network\",\"name\":\"ovirtmgmt\",\"params\":{\"required\":true,\"role\":\"management\"}},{\"id\":\"backup\",\"kind\":\"network\",\"name\":\"backup-net\",\"params\":{\"required\":true,\"role\":\"vm\"}},{\"id\":\"dbnet\",\"kind\":\"network\",\"name\":\"db-net\",\"params\":{\"required\":false,\"role\":\"vm\"}},{\"id\":\"nfs\",\"kind\":\"storage_domain\",\"name\":\"nfs-data\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"fast\",\"kind\":\"storage_domain\",\"name\":\"nfs-fast\",\"params\":{\"type\":\"nfs\"}},{\"id\":\"vm1\",\"kind\":\"vm\",\"name\":\"web-1\"},{\"id\":\"vm2\",\"kind\":\"vm\",\"name\":\"db-1\"}]}]\"\"\")\n\ndef _after(board, answer):\n    if not isinstance(answer, dict):\n        raise TypeError(\"fix(board) must return a dict with the lists ''add'' and ''remove''\")\n    edges = [[e[\"from\"], e[\"to\"]] for e in board[\"edges\"]]\n    for pair in answer.get(\"remove\", []):\n        pair = list(pair)\n        if pair in edges:\n            edges.remove(pair)\n    for pair in answer.get(\"add\", []):\n        pair = list(pair)\n        if len(pair) != 2:\n            raise ValueError(\"a link is a pair [from, to]\")\n        if pair not in edges:\n            edges.append(pair)\n    return {\"nodes\": board[\"nodes\"], \"edges\": [{\"from\": a, \"to\": b} for a, b in edges]}\n\nfor _board in _BOARDS:\n    print(_json.dumps(_after(_board, fix(_copy.deepcopy(_board)))))\n", "expected": [], "board_check": [{"pack": "virt-sim-ovirt-triage", "scenario": "engine-blind"}, {"pack": "virt-sim-ovirt-triage", "scenario": "silent-host"}, {"pack": "virt-sim-ovirt-triage", "scenario": "no-master"}, {"pack": "virt-sim-ovirt-triage-2", "scenario": "blame-disk"}]}');

